collectors.eur_usd:
const r = await fetch('https://api.frankfurter.app/latest?from=EUR&to=USD');
        const j = await r.json();
        if (!j.rates || !j.rates.USD) throw new Error('no rate');
        return Math.round(j.rates.USD * 10000) / 10000;

