collectors.ethereum_release:
const headers = { 'user-agent': 'VolatiAI/1.0', 'accept': 'application/vnd.github+json' };
        if (env.GITHUB_TOKEN) headers['authorization'] = 'Bearer ' + env.GITHUB_TOKEN;
        const r = await fetch('https://api.github.com/repos/ethereum/go-ethereum/releases?per_page=1', { headers });
        if (!r.ok) throw new Error('github status ' + r.status);
        const j = await r.json();
        if (!Array.isArray(j) || !j[0]) throw new Error('no release array: ' + JSON.stringify(j).slice(0, 100));
        return { id: j[0].id, title: j[0].name || j[0].tag_name, published_at: j[0].published_at };

collectors.hackernews_top:
const r = await fetch('https://hacker-news.firebaseio.com/v0/topstories.json');
        const ids = await r.json();
        if (!Array.isArray(ids) || !ids.length) throw new Error('no ids');
        const topId = ids[0];
        const detail = await fetch('https://hacker-news.firebaseio.com/v0/item/' + topId + '.json');
        const story = await detail.json();
        if (!story || !story.title) throw new Error('no story');
        return { id: story.id, title: story.title, by: story.by };

collectors.remoteok_latest:
const r = await fetch('https://remoteok.com/api', {
          headers: { 'user-agent': 'VolatiAI/1.0' }
        });
        if (!r.ok) throw new Error('status ' + r.status);
        const jobs = await r.json();
        if (!Array.isArray(jobs) || jobs.length < 2) throw new Error('no jobs');
        const job = jobs[1];
        if (!job || !job.id) throw new Error('no job id');
        return { id: job.id, title: (job.position || 'job') + ' @ ' + (job.company || '?') };

collectors.vscode_release:
const headers = { 'user-agent': 'VolatiAI/1.0', 'accept': 'application/vnd.github+json' };
        if (env.GITHUB_TOKEN) headers['authorization'] = 'Bearer ' + env.GITHUB_TOKEN;
        const r = await fetch('https://api.github.com/repos/microsoft/vscode/releases?per_page=1', { headers });
        if (!r.ok) throw new Error('github status ' + r.status);
        const j = await r.json();
        if (!Array.isArray(j) || !j[0]) throw new Error('no release');
        return { id: j[0].id, title: (j[0].name || j[0].tag_name) + ' (vscode)', published_at: j[0].published_at };

collectors.treasury_10y:
const r = await fetch('https://fred.stlouisfed.org/graph/fredgraph.csv?id=DGS10&cosd=2026-01-01');
        if (!r.ok) throw new Error('status ' + r.status);
        const csv = await r.text();
        const lines = csv.trim().split('\n').slice(1).filter(l => !l.endsWith(','));
        if (!lines.length) throw new Error('no data');
        const last = lines[lines.length - 1].split(',');
        const val = parseFloat(last[1]);
        if (isNaN(val)) throw new Error('invalid');
        return val;

collectors.dxy:
